INSERT INTO garden_problems (slug, name, kind, urgency, spreads, signs, looks, why, fix, prevent, plants, aliases, recheck_days, buy)
VALUES
('aphids', 'Aphids', 'Pest', 'This week', true, ARRAY['bugs-green', 'sticky', 'curl', 'ants']::text[], 'Clusters of tiny soft green, black or grey bugs on new shoots and under leaves; leaves curl and turn sticky.', 'Sap-suckers that breed fast in spring, on soft, over-fed growth. Ants farm them for their honeydew.', ARRAY['Squash small clusters with your fingers, or blast them off with a jet of water.', 'Spray pest oil (e.g. Eco-Oil) or insecticidal soap, wetting the undersides of the leaves; repeat every 5-7 days for 2-3 weeks.', 'Snip off badly curled tips.', 'Leave ladybirds and hoverfly larvae alone - they eat aphids.']::text[], 'Go easy on high-nitrogen fertiliser, check new growth weekly in spring, and grow alyssum nearby for hoverflies.', 'Chillies, capsicum, roses, kale, broccoli, lettuce, herbs, citrus', ARRAY['aphid']::text[], 5, 'pest oil'),
('spider-mites', 'Spider mites', 'Pest', 'This week', true, ARRAY['speckles', 'webbing', 'leaf-drop', 'yellow-old']::text[], 'Fine pale speckling; leaves turn dull, bronzed or silvery; fine webbing under leaves and at the tips in bad cases. The mites are dots you''d need a magnifier to see.', 'Hot, dry, still air - undercover balconies and indoors especially.', ARRAY['Hose or wipe the leaves, undersides too - mites hate humidity.', 'Spray pest oil, or a sulphur spray (not above 30°), every 5-7 days, three times.', 'Cut off and bin heavily webbed shoots.', 'Keep it away from your other plants until it''s clean.']::text[], 'Mist or hose leaves in hot, dry weather, and don''t let plants get drought-stressed.', 'Tomatoes, beans, cucumbers, strawberries, roses, indoor plants', ARRAY['mite', 'two-spotted']::text[], 5, 'miticide'),
('whitefly', 'Whitefly', 'Pest', 'This week', true, ARRAY['flies-leaf', 'sticky', 'yellow-old']::text[], 'Clouds of tiny white moth-like insects fly up when you brush the plant; flat, scale-like young under the leaves; sticky honeydew.', 'Warm weather and sheltered spots.', ARRAY['Hang yellow sticky traps beside the plant.', 'Spray pest oil or insecticidal soap under the leaves every 5-7 days for 3 weeks (eggs survive a spray; the hatchlings don''t).', 'In the cool of the morning, when they''re sluggish, a handheld vacuum takes the adults off.']::text[], 'Check under the leaves of tomatoes, beans and hibiscus in summer.', 'Tomatoes, beans, basil, hibiscus, cucumbers, zucchini', ARRAY['whitefly']::text[], 7, 'yellow sticky traps'),
('fungus-gnats', 'Fungus gnats', 'Pest', 'Keep an eye', false, ARRAY['flies-soil', 'wilt-wet', 'slow']::text[], 'Small dark flies walking on the mix and flitting around the pot; tiny clear larvae with black heads in the top few cm. Mostly a nuisance, but the larvae nibble seedling roots.', 'Mix that stays wet: overwatering, indoor pots, saucers full of water.', ARRAY['Let the top 2-3 cm of mix dry before watering again; empty the saucers.', 'Yellow sticky traps catch the adults.', 'Water from below for a couple of weeks, or top the mix with 1 cm of sand or fine gravel.', 'In bad cases, a gnat drench (Bt israelensis) kills the larvae.']::text[], 'Don''t overwater indoor pots, and use fresh bagged mix.', 'Indoor plants, seedlings, houseplants', ARRAY['fungus gnat', 'gnat']::text[], 7, 'sticky traps'),
('mealybugs', 'Mealybugs', 'Pest', 'This week', true, ARRAY['fluffy', 'sticky', 'slow']::text[], 'White, cottony, slow-moving bugs in leaf joints, under leaves and on the roots; sticky honeydew.', 'Warm, sheltered and indoor spots. They often arrive on a new plant.', ARRAY['Dab each one with a cotton bud dipped in methylated spirits (or 70% alcohol).', 'Spray pest oil every 7 days, 3-4 times, getting into the joints.', 'Tip it out of the pot: white fluff on the roots means washing the roots and repotting in fresh mix.', 'Keep it away from your other plants until it''s clean.']::text[], 'Check new plants - succulents, orchids, African violets especially - before they join the others.', 'Succulents, orchids, African violets, citrus, indoor plants, houseplants', ARRAY['mealybug', 'mealy bug']::text[], 7, 'pest oil'),
('scale', 'Scale', 'Pest', 'This week', true, ARRAY['bumps', 'sticky', 'ants', 'yellow-old']::text[], 'Small brown, white or grey bumps stuck to stems and leaf veins that don''t move; sticky leaves, black sooty mould, ants.', 'Sap-suckers hiding under a shell, in sheltered spots; ants protect them.', ARRAY['Scrape or rub them off with a fingernail or a soft toothbrush.', 'Spray pest oil (it smothers them) every 2 weeks, 2-3 times.', 'Deal with the ants that farm them (a grease band round the stem, or ant bait away from food plants).']::text[], 'Check the stems of citrus, bay and succulents a few times a year.', 'Citrus, bay, succulents, orchids, bougainvillea, gardenia', ARRAY['scale']::text[], 14, 'pest oil'),
('thrips', 'Thrips', 'Pest', 'This week', true, ARRAY['speckles', 'curl', 'flower-drop']::text[], 'Silvery or bronzed patches with tiny black dots (droppings); distorted flowers and new leaves; very small slender insects that flick away.', 'Hot, dry weather; they hide in flowers.', ARRAY['Pick off and bin damaged flowers.', 'Spray pest oil or spinosad (e.g. Yates Success) late in the day, every 7 days, three times.', 'Blue sticky traps catch them.']::text[], 'Keep plants well watered - thrips go for stressed plants.', 'Roses, chillies, tomatoes, onions, gerbera, capsicum', ARRAY['thrip']::text[], 7, 'blue sticky traps'),
('caterpillars', 'Caterpillars (cabbage white, loopers)', 'Pest', 'This week', false, ARRAY['holes']::text[], 'Ragged holes in leaves, green droppings, green caterpillars lying along the veins or loopers that arch their backs; white butterflies around.', 'Butterflies and moths lay eggs on the leaves - brassicas especially, in the warm months.', ARRAY['Turn leaves over and pick the caterpillars off.', 'Spray Bt (e.g. Dipel) - it only harms caterpillars - every 7 days while they''re about.', 'Squash the yellow egg clusters under the leaves.']::text[], 'Cover brassicas with fine insect mesh in spring and summer.', 'Kale, broccoli, cabbage, bok choy, rocket, nasturtiums, cauliflower', ARRAY['caterpillar', 'cabbage white', 'looper', 'cabbage moth']::text[], 5, 'Dipel'),
('budworm', 'Budworm', 'Pest', 'This week', false, ARRAY['holes', 'flower-drop']::text[], 'Holes bored into buds and flowers, buds that never open, small green-to-brown caterpillars inside the buds; black droppings.', 'Moths lay on petunias, geraniums and tomatoes in warm weather.', ARRAY['Pick off damaged buds - the caterpillar is usually inside.', 'Spray Bt (e.g. Dipel) or spinosad in the evening, every 7 days through summer.']::text[], 'Look into the buds weekly in summer, and start spraying early in a season where you''ve seen them before.', 'Petunia, geranium, tomatoes, snapdragon, salvia, gerbera', ARRAY['budworm']::text[], 7, 'Dipel'),
('snails-slugs', 'Snails and slugs', 'Pest', 'Act now', false, ARRAY['slime', 'holes', 'missing', 'collapse']::text[], 'Ragged holes and seedlings gone overnight; silvery slime trails; hiding under pots and rims.', 'Wet weather. They reach balconies in the pots of new plants and climb up.', ARRAY['Go out at night with a torch and pick them off.', 'Lift the pots and check under the rims and saucers.', 'Use pet-safe iron-based pellets sparingly, or a beer trap.', 'Copper tape round the rim stops them climbing in.']::text[], 'Keep pots up on pot feet, and check the pots of new plants.', 'Seedlings, lettuce, basil, strawberries, bok choy', ARRAY['snail', 'slug']::text[], 3, 'copper tape'),
('leaf-miner', 'Leaf miner', 'Pest', 'Keep an eye', false, ARRAY['trails']::text[], 'Wiggly white or pale trails inside the leaves, sometimes blotches; a tiny larva at the end of the trail.', 'Small flies (or a moth, on citrus) lay eggs in the leaf; the larvae tunnel inside it.', ARRAY['Pick off and bin affected leaves (not into the compost).', 'Squash the larva at the end of a trail between your fingers.', 'Spray pest oil every 7 days to stop the adults laying - sprays don''t reach larvae already inside.']::text[], 'Check the leaves of citrus, silverbeet and gerbera weekly in the warm months.', 'Citrus, silverbeet, spinach, tomatoes, gerbera, nasturtiums', ARRAY['leaf miner', 'leafminer']::text[], 7, 'pest oil'),
('fruit-fly', 'Fruit fly', 'Pest', 'Act now', true, ARRAY['fruit-maggots', 'fruit-drop']::text[], 'Tiny sting marks on ripening fruit, soft spots, then maggots inside; fruit dropping early.', 'Queensland fruit fly lays into ripening fruit in the warm months (worst from spring to autumn in south-east Queensland).', ARRAY['Pick and bin every stung fruit - seal it in a bag in the sun or freeze it first; never compost it.', 'Hang a fruit fly trap (a lure for the males and a bait trap for the females) near the plants.', 'Pick fruit just before it''s fully ripe and finish ripening it inside.']::text[], 'Exclusion bags or fine mesh over tomatoes, chillies and capsicums from when the fruit sets.', 'Tomatoes, chillies, capsicum, eggplant, strawberries, citrus', ARRAY['fruit fly', 'queensland fruit fly']::text[], 5, 'fruit fly trap'),
('shield-bugs', 'Stink bugs (shield bugs)', 'Pest', 'This week', false, ARRAY['big-bugs', 'wilt-dry', 'fruit-marks']::text[], 'Shield-shaped bugs - green vegetable bugs, bronze orange bugs on citrus, harlequin bugs; their young are round and colourful. Shoots wilt, fruit gets marked.', 'Sap-suckers of the warm months.', ARRAY['Knock them into a container of soapy water (wear glasses - bronze orange bugs squirt a stinging liquid).', 'Get the young (nymphs) early in the season - they''re slower and easier.', 'Pest oil works on the nymphs.']::text[], 'Check citrus in late winter for the first nymphs.', 'Citrus, tomatoes, beans, capsicum, chillies', ARRAY['stink bug', 'shield bug', 'vegetable bug', 'bronze orange', 'harlequin']::text[], 7, 'pest oil'),
('leaf-eating-ladybird', '28-spotted ladybird', 'Pest', 'Keep an eye', false, ARRAY['holes', 'big-bugs']::text[], 'Dull orange ladybirds with lots of spots, and spiky yellow larvae, scraping leaves into a lacy skeleton.', 'A leaf-eating relative of the helpful ladybirds, out in summer.', ARRAY['Pick off the adults and larvae, and squash the yellow egg clusters under the leaves.', 'Pest oil or pyrethrum on the larvae if there are lots.']::text[], 'Check zucchini, cucumbers and tomatoes weekly in summer. Leave the shiny ladybirds with few spots - they eat aphids.', 'Zucchini, cucumbers, pumpkin, tomatoes, eggplant, potatoes', ARRAY['28-spotted', 'leaf-eating ladybird']::text[], 7, 'pest oil'),
('birds-possums', 'Birds and possums', 'Pest', 'This week', false, ARRAY['missing', 'holes', 'fruit-marks']::text[], 'Fruit pecked or gone, seedlings pulled out, leaves stripped overnight.', 'Birds take ripening fruit and dig in fresh mix; possums climb to balconies at night.', ARRAY['Cover with netting or a cage (fine netting, tied tight so nothing gets tangled).', 'Pick fruit just before it''s fully ripe.', 'Protect seedlings with a cloche or a cut-down plastic bottle for the first few weeks.']::text[], 'Net fruiting plants as the fruit starts to colour.', 'Strawberries, tomatoes, chillies, seedlings, lettuce', ARRAY['bird', 'possum']::text[], 7, 'bird netting'),
('ants', 'Ants', 'Pest', 'Keep an eye', false, ARRAY['ants', 'sticky']::text[], 'Ants running up and down the stems, or a nest in the pot (the mix goes dry and fluffy, and water runs straight through).', 'Ants farm aphids, scale and mealybugs for their honeydew, and like to nest in dry pots.', ARRAY['Look for - and deal with - aphids, scale or mealybugs first; they''re usually why the ants are there.', 'A nest in the pot: stand the pot in a bucket of water for 30 minutes and they''ll move out.', 'Bait stations, away from food plants.']::text[], 'Don''t let pots dry right out.', 'Citrus, roses, chillies, any pot', ARRAY['ant']::text[], 7, 'ant bait'),
('powdery-mildew', 'Powdery mildew', 'Disease', 'This week', true, ARRAY['white-powder', 'yellow-old', 'curl']::text[], 'White to grey powdery patches on the tops of leaves, spreading until the leaves yellow and die.', 'Dry leaves in humid air, crowding and still air - late summer and autumn especially.', ARRAY['Pick off the worst leaves and bin them.', 'Spray every 7 days: 1 part full-cream milk to 9 parts water, or potassium bicarbonate (e.g. Eco-Carb), or sulphur (not above 30°).', 'Give it more space and air.']::text[], 'Water the mix, not the leaves; space the pots; choose mildew-resistant zucchini and cucumbers.', 'Zucchini, cucumbers, pumpkin, peas, roses, zinnia, begonia', ARRAY['powdery mildew', 'mildew']::text[], 7, 'eco-carb'),
('downy-mildew', 'Downy mildew', 'Disease', 'This week', true, ARRAY['spots', 'grey-fuzz', 'yellow-old']::text[], 'Yellow, angular patches on top of the leaves with grey-purple fuzz underneath, older leaves first, after wet weather.', 'Cool, wet, humid weather with water sitting on the leaves overnight.', ARRAY['Remove and bin affected leaves.', 'Water in the morning, at the base.', 'A copper-based fungicide protects new leaves; repeat after rain.']::text[], 'Don''t crowd pots; keep the leaves dry; let the air through.', 'Lettuce, basil, cucumbers, impatiens, kale, broccoli', ARRAY['downy mildew']::text[], 7, 'copper fungicide'),
('root-rot', 'Root rot', 'Disease', 'Act now', false, ARRAY['wilt-wet', 'mushy', 'yellow-old', 'leaf-drop']::text[], 'Wilting although the mix is wet; yellowing lower leaves; brown, mushy, smelly roots; a dark, soft stem base.', 'Mix that stays waterlogged: no drainage holes, a saucer full of water, a pot far too big, heavy old mix.', ARRAY['Stop watering; tip it out of the pot and look at the roots.', 'Cut off brown, mushy roots with clean scissors; keep the firm white ones.', 'Repot in fresh, free-draining mix, in a pot with holes no bigger than the root ball.', 'Water lightly and keep it out of hot sun for a week. If the stem base is mushy, take a cutting from a healthy shoot instead.']::text[], 'Pots with drainage holes, saucers emptied after rain, and water only when the top few cm are dry.', 'Succulents, lavender, rosemary, herbs, indoor plants, orchids, gerbera, houseplants', ARRAY['root rot', 'crown rot', 'rot', 'phytophthora']::text[], 3, 'free-draining potting mix'),
('damping-off', 'Damping off', 'Disease', 'Act now', true, ARRAY['collapse', 'mushy']::text[], 'Seedlings that looked fine suddenly topple over, pinched and dark at the soil line.', 'Soil fungi in cold, wet, crowded seedling trays with still air.', ARRAY['Remove fallen seedlings and the mix around them.', 'Let the tray dry a little, water from below, and give it airflow (a small fan helps indoors).', 'Sow again in fresh seed-raising mix in a clean tray.']::text[], 'Fresh seed-raising mix, clean trays, sow thinly, don''t overwater, and keep air moving.', 'Seedlings', ARRAY['damping off']::text[], 3, 'seed raising mix'),
('rust', 'Rust', 'Disease', 'This week', true, ARRAY['orange-pustules', 'yellow-old', 'leaf-drop']::text[], 'Orange, rust-brown or yellow powdery bumps under the leaves with pale spots above; leaves yellow and fall.', 'A fungus spread by wind and splashing water in humid weather.', ARRAY['Remove and bin affected leaves (not into the compost).', 'Spray a sulphur or copper fungicide every 7-10 days.', 'Water at the base, keeping the leaves dry.']::text[], 'Space for airflow; clear up fallen leaves.', 'Geranium, snapdragon, beans, mint, garlic, roses, frangipani', ARRAY['rust']::text[], 7, 'copper fungicide'),
('leaf-spot', 'Leaf spot (incl. black spot)', 'Disease', 'This week', true, ARRAY['spots', 'yellow-old', 'leaf-drop']::text[], 'Brown or black spots, often ringed with yellow, that join up; lower leaves first.', 'Fungi or bacteria splashed from the mix onto the leaves in wet weather.', ARRAY['Pick off spotted leaves and bin them.', 'Mulch the mix surface so water doesn''t splash up.', 'A copper-based spray protects the new growth; repeat after rain.']::text[], 'Water the mix, not the leaves, and in the morning.', 'Tomatoes, capsicum, strawberries, roses, silverbeet, chillies', ARRAY['leaf spot', 'black spot', 'septoria', 'bacterial spot', 'blight']::text[], 7, 'copper fungicide'),
('grey-mould', 'Grey mould (botrytis)', 'Disease', 'This week', true, ARRAY['grey-fuzz', 'mushy', 'fruit-rot']::text[], 'Fuzzy grey mould on flowers, fruit (strawberries!) or wounds on stems, with soft brown rot beneath.', 'Cool, humid, still air, and dead flowers and leaves left on the plant.', ARRAY['Cut off and bin everything mouldy, and a little healthy tissue with it.', 'More airflow; water in the morning; keep fruit off the wet mix (straw under strawberries).', 'Pick ripe fruit promptly.']::text[], 'Take off spent flowers and dead leaves, and don''t crowd.', 'Strawberries, lettuce, tomatoes, geranium, begonia', ARRAY['botrytis', 'grey mould']::text[], 5, 'sugar cane mulch'),
('sooty-mould', 'Sooty mould', 'Disease', 'Keep an eye', false, ARRAY['sticky', 'black-coat']::text[], 'A black, sooty coating on the leaves that wipes off.', 'It grows on the honeydew of aphids, scale, mealybugs or whitefly - those are the real problem.', ARRAY['Find and treat the sap-sucker: look for aphids, scale, mealybugs or whitefly.', 'Wipe or hose the black off - pest oil also loosens it as it dries.']::text[], 'Keep sap-suckers under control.', 'Citrus, gardenia, bay, hibiscus', ARRAY['sooty mould']::text[], 14, 'pest oil'),
('soil-mould', 'Mould or mushrooms on the mix', 'Disease', 'Keep an eye', false, ARRAY['soil-mould']::text[], 'White fluffy or crusty mould on top of the mix, sometimes little yellow mushrooms.', 'Harmless fungi breaking down organic matter in mix that stays damp. It doesn''t hurt the plant.', ARRAY['Scrape off the top layer and loosen the surface.', 'Water less often, letting the top dry out, and give it more air and light.']::text[], 'Don''t keep indoor pots constantly wet.', 'Indoor plants, seedlings, houseplants', ARRAY['mould', 'mushroom']::text[], 7, NULL),
('nitrogen', 'Hungry for nitrogen', 'Feeding', 'This week', false, ARRAY['yellow-old', 'slow', 'pale']::text[], 'The older, lower leaves turn evenly pale yellow first; the plant grows slowly and looks washed out.', 'Potted plants use up the food in the mix in 6-8 weeks, and watering washes nitrogen out.', ARRAY['Give a liquid fertiliser (an all-purpose soluble, or fish emulsion with seaweed) now and every 1-2 weeks while it''s growing.', 'Add slow-release pellets to the top of the mix for the season.']::text[], 'Feed regularly from about 6 weeks after potting (the app reminds you when feeding is due).', 'Lettuce, kale, silverbeet, herbs, basil, any pot over two months old', ARRAY['nitrogen']::text[], 14, 'liquid fertiliser'),
('magnesium', 'Short of magnesium', 'Feeding', 'Keep an eye', false, ARRAY['yellow-veins']::text[], 'Yellowing between the veins of the older leaves while the veins stay green; sometimes reddish blotches.', 'Potted plants, heavy potash feeding, or old mix.', ARRAY['Dissolve 1 tablespoon of Epsom salts in 4 L of water and water or spray it on; repeat in 2-3 weeks.', 'Use a complete fertiliser that lists magnesium.']::text[], 'A complete fertiliser (with trace elements) rather than straight potash.', 'Citrus, tomatoes, capsicum, roses, chillies', ARRAY['magnesium']::text[], 21, 'epsom salts'),
('iron', 'Short of iron', 'Feeding', 'Keep an eye', false, ARRAY['yellow-new']::text[], 'The newest leaves turn yellow while their veins stay green.', 'Mix that''s too alkaline (tap water, lime) so the roots can''t take up iron - acid-lovers show it first.', ARRAY['Water with iron chelate (as the label says).', 'Repot acid-lovers (gardenia, blueberry, azalea) in azalea and camellia mix.']::text[], 'Use the right mix for acid-loving plants.', 'Gardenia, blueberries, citrus, azalea, camellia', ARRAY['iron', 'chlorosis']::text[], 21, 'iron chelate'),
('phosphorus', 'Purple leaves (phosphorus)', 'Feeding', 'Keep an eye', false, ARRAY['purple', 'slow']::text[], 'A purple or red tinge on the leaves (often underneath) and slow growth - common in seedlings in cold weather.', 'Cold mix slows the uptake of phosphorus; or the mix has little of it.', ARRAY['Usually it goes once the weather warms up.', 'Feed with a complete fertiliser, or one for flowers and fruit.']::text[], 'Raise seedlings somewhere warm.', 'Tomato and capsicum seedlings, kale, broccoli, seedlings', ARRAY['phosphorus']::text[], 14, NULL),
('potassium', 'Short of potassium', 'Feeding', 'This week', false, ARRAY['brown-edges', 'no-fruit', 'yellow-old']::text[], 'Older leaves scorch brown at the edges and tips, sometimes with yellowing; poor flowers and fruit.', 'Hungry pots, fruiting plants especially.', ARRAY['Feed with a flower and fruit fertiliser (higher potash) every 1-2 weeks while it''s flowering and fruiting.', 'Or sprinkle a little sulphate of potash and water it in.']::text[], 'Switch to a flower and fruit fertiliser when flowering starts.', 'Tomatoes, chillies, strawberries, citrus, capsicum, zucchini', ARRAY['potassium', 'potash']::text[], 14, 'flower and fruit fertiliser'),
('fertiliser-burn', 'Too much fertiliser', 'Feeding', 'Act now', false, ARRAY['brown-edges', 'crust', 'wilt-wet']::text[], 'Brown, crispy leaf tips and edges, a white crust on the mix or pot, wilting though the mix is moist - often after a strong feed.', 'Too much or too strong fertiliser: salts build up and burn the roots.', ARRAY['Flush the pot: water slowly with plenty of water until it pours out the bottom - twice.', 'Skip feeding for 3-4 weeks, then feed at half strength.']::text[], 'Follow the label rates, and liquid-feed onto moist mix, never dry.', 'Any pot, seedlings, indoor plants', ARRAY['fertiliser burn', 'salt']::text[], 7, NULL),
('underwatering', 'Too dry', 'Watering', 'Act now', false, ARRAY['wilt-dry', 'brown-edges', 'leaf-drop', 'flower-drop']::text[], 'Drooping leaves, dry mix shrinking from the pot''s sides, crispy edges; it perks up after a drink.', 'Small pots on hot or windy balconies dry out fast - twice a day in a summer heatwave.', ARRAY['Soak it: stand the pot in a bucket of water for 30 minutes if the mix has shrunk away from the sides.', 'Move it out of the afternoon sun for a day.', 'From now on, water deeply when the top few cm are dry, rather than a little often.']::text[], 'Bigger pots, self-watering pots or wicking trays, and mulch on the mix.', 'Any pot, hanging baskets, lettuce, seedlings', ARRAY['drought', 'dry']::text[], 2, 'self watering pot'),
('overwatering', 'Too wet', 'Watering', 'This week', false, ARRAY['wilt-wet', 'yellow-old', 'flies-soil', 'slow']::text[], 'Yellowing, droopy leaves although the mix is damp; fungus gnats; slow growth.', 'Watering by the calendar instead of by the mix; poor drainage; saucers holding water.', ARRAY['Stop, and let the top few cm of mix dry out.', 'Empty the saucers and check the drainage holes aren''t blocked.', 'If it hasn''t picked up in a few days, check the roots for rot (see Root rot).']::text[], 'Push a finger 3 cm into the mix and water only if it''s dry there.', 'Succulents, indoor plants, lavender, rosemary, houseplants', ARRAY['overwater', 'waterlogged']::text[], 3, NULL),
('water-repellent', 'Mix won''t take water', 'Watering', 'Act now', false, ARRAY['water-runs', 'wilt-dry']::text[], 'Water runs straight through, or down the sides and out, and the mix stays dry inside.', 'Potting mix that dries out completely becomes water repellent.', ARRAY['Stand the pot in a bucket of water until the bubbles stop.', 'Add a soil wetter (wetting agent) to the water.']::text[], 'Don''t let pots dry right out, and use a mix that has wetting agent in it.', 'Any pot, hanging baskets', ARRAY['hydrophobic', 'water repellent']::text[], 3, 'soil wetter'),
('blossom-end-rot', 'Blossom end rot', 'Watering', 'This week', false, ARRAY['fruit-rot-end']::text[], 'A dark, leathery, sunken patch on the bottom of tomatoes, capsicums or zucchini.', 'Not a disease: the fruit couldn''t get calcium, nearly always because watering was uneven (the pot dried out, then was soaked).', ARRAY['Pick off affected fruit - the rest of the plant is fine.', 'Water deeply and regularly; a self-watering pot or mulch on top keeps moisture even.', 'Move it to a bigger pot if it dries out every day in summer.']::text[], 'Even watering, pots of 20 L or more for tomatoes, and a little gypsum or lime in the mix at planting.', 'Tomatoes, capsicum, zucchini, eggplant, chillies', ARRAY['blossom end rot']::text[], 7, 'mulch'),
('fruit-split', 'Splitting fruit', 'Watering', 'Keep an eye', false, ARRAY['fruit-split']::text[], 'Cracks around the top or down the side of ripening tomatoes, cherries or citrus.', 'A big drink after a dry spell: the inside grows faster than the skin.', ARRAY['Pick split fruit and use it straight away.', 'Pick nearly ripe fruit before heavy rain that''s forecast.']::text[], 'Water evenly, and mulch.', 'Tomatoes, cherry tomatoes, citrus, figs', ARRAY['split']::text[], 7, NULL),
('root-bound', 'Outgrown its pot', 'Conditions', 'Keep an eye', false, ARRAY['roots-out', 'wilt-dry', 'slow']::text[], 'Roots poking out the drainage holes or circling on the surface; dries out within hours; growth stalls.', 'It has filled its pot.', ARRAY['Pot it up one size (about 5 cm wider) with fresh mix.', 'Tease out circling roots first.', 'To keep it in the same pot: trim a third off the roots and add fresh mix.']::text[], 'Repot perennials every 1-2 years in spring.', 'Herbs, chillies, citrus, indoor plants, succulents, houseplants', ARRAY['root bound', 'pot bound']::text[], 14, 'potting mix'),
('sunburn', 'Sunburn', 'Conditions', 'This week', false, ARRAY['bleached']::text[], 'Bleached white or papery brown patches on the leaves (or fruit) facing the sun, after a hot day or a move outside.', 'Sudden strong sun - plants moved from indoors or shade, or a heatwave on a west-facing balcony.', ARRAY['Give shade (shade cloth, or move it) on hot afternoons.', 'Leave damaged leaves on until new ones grow - they still feed the plant.', 'Harden off plants over a week: an hour more sun each day.']::text[], 'Harden off new plants, and use shade cloth on west-facing balconies in summer.', 'Seedlings, lettuce, indoor plants, capsicum, houseplants', ARRAY['sunburn', 'scorch']::text[], 7, 'shade cloth'),
('low-light', 'Not enough light', 'Conditions', 'Keep an eye', false, ARRAY['leggy', 'slow', 'no-fruit', 'leaf-drop', 'pale']::text[], 'Long, thin, pale stems leaning toward the light; few flowers or fruit.', 'Not enough direct sun - common on south-facing balconies and indoors.', ARRAY['Move it to your sunniest spot, or add a grow light for 12-16 hours a day.', 'Pinch out the tips to make it bushier; bury the stretched stems of seedlings deeper when potting on.', 'Turn the pot weekly.']::text[], 'Match plants to your spaces'' sun (the app warns when a space gets less sun than a plant wants).', 'Seedlings, tomatoes, basil, indoor plants, herbs', ARRAY['leggy', 'light']::text[], 14, 'grow light'),
('heat-stress', 'Heat stress', 'Conditions', 'This week', false, ARRAY['flower-drop', 'no-fruit', 'wilt-dry']::text[], 'Flowers fall without setting fruit in hot spells; leaves droop at midday and recover in the evening.', 'Above about 32° (or with nights over about 24°) tomatoes, capsicums and beans drop their flowers.', ARRAY['Shade cloth (30-50%) on the hottest afternoons.', 'Water deeply in the morning and mulch the mix.', 'Wait: fruit sets again when it cools down.']::text[], 'Today''s weather tips warn of hot days.', 'Tomatoes, capsicum, beans, lettuce, chillies', ARRAY['heat']::text[], 5, 'shade cloth'),
('pollination', 'Flowers but no fruit', 'Conditions', 'Keep an eye', false, ARRAY['no-fruit', 'fruit-drop']::text[], 'Lots of flowers but little or no fruit, or tiny fruit that shrivels and drops (zucchini, cucumbers).', 'Bees don''t reach a high or enclosed balcony, and zucchini need pollen moved from male to female flowers.', ARRAY['Zucchini and cucumbers: in the morning, pick a male flower (thin stem, no baby fruit) and dab its centre onto a female flower (a tiny fruit behind it).', 'Tomatoes, chillies and capsicum: flick or gently shake the flower trusses on a warm morning.', 'Grow flowers (alyssum, basil left to flower) to bring the bees.']::text[], 'Hand pollinate as a habit on a high balcony.', 'Zucchini, cucumbers, pumpkin, tomatoes, chillies, capsicum, strawberries', ARRAY['pollination']::text[], 7, NULL),
('cold-damage', 'Cold damage', 'Conditions', 'This week', false, ARRAY['black-leaves']::text[], 'Leaves blackened, limp or see-through after a cold night; tender tips die back.', 'Basil, chillies, tomatoes and tropical plants are hurt below about 5-10°.', ARRAY['Don''t cut the damaged parts off until the weather warms - they shelter what''s below.', 'Move tender pots against the wall or inside on cold nights.']::text[], 'Today''s weather tips warn of cold nights.', 'Basil, chillies, tomatoes, impatiens, indoor plants', ARRAY['cold', 'frost']::text[], 14, 'frost cloth'),
('wind', 'Wind damage', 'Conditions', 'This week', false, ARRAY['brown-edges', 'leaf-drop', 'wilt-dry', 'torn']::text[], 'Torn leaves, browned and dried on the windward side; pots blown over; drying out fast.', 'Exposed, high balconies.', ARRAY['Move tender plants behind sturdier ones or against the wall.', 'Add a windbreak (shade cloth or a screen along the railing).', 'Water more often on windy days.']::text[], 'Today''s weather tips warn of strong gusts.', 'Tomatoes, basil, lettuce, sunflowers, hanging baskets', ARRAY['wind']::text[], 7, 'shade cloth'),
('bolting', 'Running to seed (bolting)', 'Conditions', 'Keep an eye', false, ARRAY['bolting']::text[], 'Lettuce, coriander, rocket or bok choy shoot up a flower stalk and the leaves turn bitter.', 'Heat, long days or stress tell them to make seed.', ARRAY['Pick what you can now.', 'Let a few flower for the bees and to save seed, then sow again.', 'Next time sow in the cooler months, in afternoon shade, a little every 2-3 weeks.']::text[], 'Sow these in their season (the guide''s sowing months).', 'Lettuce, coriander, rocket, bok choy, spinach, basil', ARRAY['bolting', 'bolt']::text[], 7, NULL),
('transplant-shock', 'Transplant shock', 'Conditions', 'Keep an eye', false, ARRAY['wilt-dry', 'leaf-drop', 'slow']::text[], 'Wilting and drooping in the days after potting or moving; a few yellow leaves.', 'Disturbed roots, and new sun or wind.', ARRAY['Water it in well (a seaweed solution helps the roots), then keep the mix just moist.', 'Give it a few days of shade or shelter.', 'Don''t feed it for a week or two.']::text[], 'Plant out in the cool of the evening and water in with seaweed solution.', 'Seedlings, any new plant', ARRAY['transplant']::text[], 3, 'seaweed solution')
