-- Gardening: the plant doctor (2026-10-18). Common problems of pots and balconies in Australia - bugs, diseases,
-- feeding, watering, sun and weather - each with the signs to look for (keys of garden_doctor.SIGNS), why it
-- happens, what to do (steps), how to prevent it, which plants usually get it, and how many days until you look
-- again. Written for this app (generated by a script; not copied from anywhere). Idempotent.
BEGIN;

CREATE TABLE IF NOT EXISTS garden_problems (
    problem_id    serial PRIMARY KEY,
    slug          text NOT NULL UNIQUE,
    name          text NOT NULL,
    kind          text NOT NULL CHECK (kind IN ('Pest', 'Disease', 'Feeding', 'Watering', 'Conditions')),
    urgency       text NOT NULL CHECK (urgency IN ('Act now', 'This week', 'Keep an eye')),
    spreads       boolean NOT NULL DEFAULT false,      -- move it away from your other plants
    signs         text[] NOT NULL DEFAULT '{}',
    looks         text NOT NULL,
    why           text,
    fix           text[] NOT NULL DEFAULT '{}',        -- what to do, in order
    prevent       text,
    plants        text,                                -- plants that usually get it (matched against yours)
    aliases       text[] NOT NULL DEFAULT '{}',        -- words for it in the guide's "pests" notes
    recheck_days  integer NOT NULL DEFAULT 7 CHECK (recheck_days BETWEEN 1 AND 60),
    buy           text                                 -- what to look for at the shop
);

ON CONFLICT (slug) DO NOTHING;

COMMIT;
